import { Box, Button, Typography } from '@mui/material';
import React, { useState, useEffect, useMemo } from 'react';
import { GameOver } from '../ChuckNorrisFact';

// Constantes pour la taille de la grille et les bateaux
const GRID_SIZE = 10;
const CASESIZE = 30;
const SHIPS = [
  { name: 'Porte-avions', size: 5 },
  { name: 'Croiseur', size: 4 },
  { name: 'Sous-marin', size: 3 },
  { name: 'Destroyer', size: 3 },
  { name: 'Patrouilleur', size: 2 },
];

// Génère une grille vide
const createEmptyGrid = () => Array.from({ length: GRID_SIZE }, () => Array(GRID_SIZE).fill(null));

// Place les bateaux aléatoirement sur la grille
const placeShipsRandomly = () => {
  const grid = createEmptyGrid();
  for (const ship of SHIPS) {
    let placed = false;
    while (!placed) {
      const isHorizontal = Math.random() < 0.5;
      const row = Math.floor(Math.random() * GRID_SIZE);
      const col = Math.floor(Math.random() * GRID_SIZE);
      
      // Vérifie si le bateau peut être placé
      if (canPlaceShip(grid, row, col, ship.size, isHorizontal)) {
        placeShip(grid, row, col, ship.size, isHorizontal, ship.name);
        placed = true;
      }
    }
  }
  return grid;
};

// Vérifie si un bateau peut être placé
const canPlaceShip = (grid, row, col, size, isHorizontal) => {
  for (let i = 0; i < size; i++) {
    const r = isHorizontal ? row : row + i;
    const c = isHorizontal ? col + i : col;
    if (r >= GRID_SIZE || c >= GRID_SIZE || grid[r][c]) return false;
  }
  return true;
};

// Place un bateau sur la grille
const placeShip = (grid, row, col, size, isHorizontal, shipName) => {
  for (let i = 0; i < size; i++) {
    const r = isHorizontal ? row : row + i;
    const c = isHorizontal ? col + i : col;
    grid[r][c] = shipName;
  }
};

// Composant principal de la Bataille Navale
export const BattleshipGame = () => {
  const [playerGrid, setPlayerGrid] = useState(placeShipsRandomly());
  const [aiGrid, setAiGrid] = useState(placeShipsRandomly());
  const [playerShots, setPlayerShots] = useState(createEmptyGrid());
  const [aiShots, setAiShots] = useState(createEmptyGrid());
  const [turn, setTurn] = useState('player');
  const [gameOver, setGameOver] = useState(false);
  const [gridBateaux, setgridBateaux] = useState([]);
  const [currentBateau, setCurrentBateau] = useState();

  const gridComplete = gridBateaux.length===SHIPS.length;
  const selectBateau=bat=>{
    if(!gridComplete)
        setCurrentBateau(bat);
  }
  const poseBateau=(row, col)=>{
    setPlayerGrid(oldGrd=>{
        const newGrid=[...oldGrd];
        placeShip(newGrid, row, col, currentBateau.size, currentBateau.isHorizontal, currentBateau.name);
        return newGrid;
    });
    setgridBateaux(b=>b.concat({...currentBateau}));
    setCurrentBateau(null);
  }
  const reset = ()=>{
    setGameOver(false);
    setAiGrid(placeShipsRandomly());
    setPlayerShots(createEmptyGrid());
    setAiShots(createEmptyGrid());
    setTurn('player');
    setPlayerGrid(createEmptyGrid())
  }
  // Tir d’un joueur sur la grille de l’adversaire
  const handlePlayerShot = (row, col) => {
    if (playerShots[row][col] || gameOver || !gridComplete) return;
    const newShots = [...playerShots];
    newShots[row][col] = aiGrid[row][col] ? 'hit' : 'miss';
    setPlayerShots(newShots);
    if (isAllShipsSunk(aiGrid, newShots)) {
      setGameOver(true);
      alert("Félicitations ! Vous avez gagné !");
    } else {
      setTurn('ai');
    }
  };

  // L'IA tire aléatoirement
  useEffect(() => {
    if (turn === 'ai' && !gameOver) {
      const availableShots = [];
      aiShots.forEach((row, rIdx) =>
        row.forEach((cell, cIdx) => {
          if (!cell) availableShots.push({ row: rIdx, col: cIdx });
        })
      );
      const { row, col } = availableShots[Math.floor(Math.random() * availableShots.length)];
      const newAiShots = [...aiShots];
      newAiShots[row][col] = playerGrid[row][col] ? 'hit' : 'miss';
      setAiShots(newAiShots);
      if (isAllShipsSunk(playerGrid, newAiShots)) {
        setGameOver(true);
        alert("Vous avez perdu ! L'IA a gagné.");
      } else {
        setTurn('player');
      }
    }
  }, [turn, gameOver, aiShots, playerGrid]);

  return (
    <div style={{ display: 'flex', gap: '2rem', justifyContent:'space-evenly' }}>
        <Box>
            <Button onClick={reset}>Reset</Button>
            <ChoosableShip currentBateau={currentBateau} disabled={gridComplete}
                selectBateau={selectBateau}/>
        </Box>
      <div>
        <h2>Votre Grille</h2>
        <GridDisplay grid={playerGrid} shots={aiShots} poseBateau={poseBateau}
        currentBateau={currentBateau} isPlayer={true} />
      </div>
      <div>
        <h2>Grille de l'IA</h2>
        <GridDisplay grid={aiGrid} shots={playerShots} isPlayer={false} onCellClick={handlePlayerShot} />
      </div>
      <GameOver gameName="Bataille navale" open={gameOver} score={'victoire ou pas'} 
    handleClose={() => { setGameOver(false) }} handleRestart={reset} />
    </div>
  );
};

const ChoosableShip=({currentBateau, selectBateau, disabled})=>{
    const bateaux = [];
        for (const ship of SHIPS) {
            const cases=[];
            for(let c=0;c<ship.size;c++)
                cases.push({selected:ship.name===currentBateau?.name});
            bateaux.push({name:ship.name, cases, isHorizontal:true, size:ship.size})
        }
        
    return <Box sx={{width:'100%'}}>
        {bateaux.map((bat,bidx)=>{
            return <Box key={'b'+bidx} onClick={()=>{selectBateau(bat)}}
            sx={{display:'flex', alignItems:'center'}}>
                {bat.cases.map((caze, c)=>{
                    return <div key={'d'+c} style={{border:'1px solid black',width:CASESIZE, height:CASESIZE
                        , background:caze.selected?'#efe':'#eee'}}></div>;
                })}
                <Typography sx={{marginLeft:'10px'}}>{bat.name}</Typography>
                </Box>
        })}
    </Box>
}
// Affiche une grille de jeu
const GridDisplay = ({currentBateau,poseBateau, grid, shots, isPlayer, onCellClick }) => {
    const onMouseOver=(evt, row, cell)=>{
        if(currentBateau!=null){
            if(canPlaceShip(grid, row, cell, currentBateau.size, currentBateau.isHorizontal))
                evt.target.style.backgroundColor='green';
            else
                evt.target.style.backgroundColor='red';
         }
    }
    const onMouseOut=(evt,origColor)=>{
        evt.target.style.backgroundColor=origColor;
    }
    const onClick=(evt, rIdx, cIdx)=>{
        if(!isPlayer && onCellClick)
            onCellClick(rIdx, cIdx);
        if(isPlayer && currentBateau!=null){
            poseBateau(rIdx, cIdx);
        }
    }
   
  return (
    <div style={{ display: 'grid', gridTemplateColumns: `repeat(${GRID_SIZE}, 30px)` }}>
      {grid.map((row, rIdx) =>
        row.map((cell, cIdx) => {
          const shot = shots[rIdx][cIdx];
          const isHit = shot === 'hit';
          const isMiss = shot === 'miss';
          const isShip = isPlayer && cell;
          const backgroundColor = isHit ? 'red' : isMiss ? 'lightblue' : isShip ? 'gray' : 'white';
        
          
          return (
            <div
              key={`${rIdx}-${cIdx}`}
              onClick={evt=>{onClick(evt,rIdx,cIdx)}}
              onMouseOver={evt=>{ return onMouseOver(evt,rIdx,cIdx);}}
             
              onMouseOut={(evt)=>{onMouseOut(evt,backgroundColor)}}
              style={{
                width: CASESIZE,
                height: CASESIZE,
                border: '1px solid black',
                
                backgroundColor,
                cursor: !isPlayer ? 'pointer' : 'default',
              }}
            />
          );
        })
      )}
    </div>
  );
};

// Vérifie si tous les bateaux sont coulés
const isAllShipsSunk = (grid, shots) => {
  for (let row = 0; row < GRID_SIZE; row++) {
    for (let col = 0; col < GRID_SIZE; col++) {
      if (grid[row][col] && shots[row][col] !== 'hit') {
        return false;
      }
    }
  }
  return true;
};
