function isMovesLeft(board) {
  for (let row of board) {
      if (row.includes(0)) { // 0 représente une case vide
          return true;
      }
  }
  return false;
}

function evaluate(board) {
  // Vérifie les lignes pour une victoire
  for (let row of board) {
      if (row[0] === row[1] && row[1] === row[2] && row[0] !== 0) {
          return row[0] === 1 ? 10 : -10;
      }
  }

  // Vérifie les colonnes pour une victoire
  for (let col = 0; col < 3; col++) {
      if (board[0][col] === board[1][col] && board[1][col] === board[2][col] && board[0][col] !== 0) {
          return board[0][col] === 1 ? 10 : -10;
      }
  }

  // Vérifie les diagonales pour une victoire
  if (board[0][0] === board[1][1] && board[1][1] === board[2][2] && board[0][0] !== 0) {
      return board[0][0] === 1 ? 10 : -10;
  }
  if (board[0][2] === board[1][1] && board[1][1] === board[2][0] && board[0][2] !== 0) {
      return board[0][2] === 1 ? 10 : -10;
  }

  return 0; // Aucune victoire
}

function minimax(board, depth, isMaximizing) {
  let score = evaluate(board);

  // Si un joueur a gagné
  if (score === 10 || score === -10) {
      return score;
  }

  // Si aucun coup n'est possible
  if (!isMovesLeft(board)) {
      return 0;
  }

  if (isMaximizing) {
      let best = -Infinity;

      for (let i = 0; i < 3; i++) {
          for (let j = 0; j < 3; j++) {
              if (board[i][j] === 0) {
                  board[i][j] = 1; // Maximizing player (1)
                  best = Math.max(best, minimax(board, depth + 1, false));
                  board[i][j] = 0;
              }
          }
      }
      return best;
  } else {
      let best = Infinity;

      for (let i = 0; i < 3; i++) {
          for (let j = 0; j < 3; j++) {
              if (board[i][j] === 0) {
                  board[i][j] = 2; // Minimizing player (2)
                  best = Math.min(best, minimax(board, depth + 1, true));
                  board[i][j] = 0;
              }
          }
      }
      return best;
  }
}

function findBestMove(board) {
  let bestVal = -Infinity;
  let bestMove = { row: -1, col: -1 };

  for (let i = 0; i < 3; i++) {
      for (let j = 0; j < 3; j++) {
          if (board[i][j] === 0) {
              board[i][j] = 1; // Maximizing player (1)
              let moveVal = minimax(board, 0, false);
              board[i][j] = 0;
              if (moveVal > bestVal) {
                  bestVal = moveVal;
                  bestMove = { row: i, col: j };
              }
          }
      }
  }
  return bestMove;
}

