const Regles = ({ regle }) => {
  const [anchorEl, setAnchorEl] = useState(null);

  const handlePopoverOpen = (event) => {
    setAnchorEl(event.currentTarget);
  };

  const handlePopoverClose = () => {
    setAnchorEl(null);
  };

  if (regle == null)
    return null;

  return (
    <>
      <Box className='reglesInfo' onClick={handlePopoverOpen}>
        <InfoOutlined color='primary' />
      </Box>
      <Popover
        open={Boolean(anchorEl)}
        anchorEl={anchorEl}
        onClose={handlePopoverClose}
        anchorOrigin={{
          vertical: 'bottom',
          horizontal: 'right',
        }}
        transformOrigin={{
          vertical: 'top',
          horizontal: 'right',
        }}
      >
        <Box className="regleText">
          {regle}
        </Box>
      </Popover>
    </>
  );
};
export const AppList = ({ apps, onSelectApp }) => {

  const [groupOpened, setGroupOpened] = useState(-1);
  const { getScoreByGame } = useGlobalScores();

  return (
    <div className="app-list">
      {apps.map((app, index) => (
        <Box key={index} className="app-item">
          <Box
            onClick={() => setGroupOpened(groupOpened === index ? -1 : index)}
            className="metal-box"
          >
            <Typography color="text.primary">{app.divider}</Typography>
          </Box>

          <Collapse in={groupOpened === index}>
            {app.children.map((singApp, sidx) => {
              const scoreData = getScoreByGame(singApp.id||singApp.name); // <-- important : singApp.id
              const scoreDisplay =
                scoreData?.score && scoreData.score > 0
                  ? `🏆 ${scoreData.score}`
                  : null;

              return (
                <Box key={'s' + sidx} className="app-subitem">
                  <Box sx={{ display: 'flex', flex:1, alignItems: 'center' }}>
                    <Alert
                      variant="outlined"
                      sx={{
                        flex: 2,
                        backgroundColor: '#fffdfc',
                        display: 'flex',
                        justifyContent: 'start',
                        alignItems: 'center',
                        px: 2
                      }}
                      onClick={() => onSelectApp(singApp)}
                      severity={singApp.status}
                    >
                      <Typography>{singApp.name}</Typography>
                      <Typography variant='caption'> {singApp.description}</Typography>
                      {scoreDisplay && (
                        <Typography
                          variant="caption"
                          sx={{ ml: 2, color: '#777' }}
                        >
                          {scoreDisplay}
                        </Typography>
                      )}
                    </Alert>
                  </Box>

                </Box>
              );
            })}
          </Collapse>
        </Box>
      ))}
    </div>
  );
};

