import * as React from 'react';
import { Box, Typography, Collapse, IconButton } from '@mui/material';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';

export const JeuPanel = ({ jeu }) => {
  const [open, setOpen] = React.useState(false);

  return (
    <Box height="100%" display="flex" flexDirection="column">
      <Box  sx={{
          backgroundColor: '#f8e970', // Couleur d'arrière-plan personnalisée
          padding: 1,
          borderRadius: 8,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
        }}>
        <Typography variant="h5" sx={{
            fontFamily: 'Montserrat', // Police personnalisée
            fontWeight: 'bold', marginLeft:4,
             textShadow: '17px 12px 3px rgba(100,0,0,0.3)',
            color: '#833',
          }}>{jeu?.name}</Typography>
        <IconButton onClick={() => setOpen(!open)}>
          <ExpandMoreIcon />
        </IconButton>
      </Box>
      <Collapse in={open} timeout="auto" unmountOnExit>
        <Box p={2}>
          <Typography variant="body1">{jeu?.regles}</Typography>
        </Box>
      </Collapse>
      {jeu?.component}
    </Box>
  );
};